import React from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { FileText, Share2, Target, TrendingUp, CheckCircle, Award } from 'lucide-react';
import './Dashboard.css';

// Sample data for the last 14 days
const activityData = [
  { day: '1 Sun', xp: 0 }, { day: '2 Mon', xp: 0 }, { day: '3 Tue', xp: 0 },
  { day: '4 Wed', xp: 0 }, { day: '5 Thu', xp: 0 }, { day: '6 Fri', xp: 0 },
  { day: '7 Sat', xp: 0 }, { day: '8 Sun', xp: 0 }, { day: '9 Mon', xp: 0 },
  { day: '10 Tue', xp: 0 }, { day: '11 Wed', xp: 0 }, { day: '12 Thu', xp: 0 },
  { day: '13 Fri', xp: 0 }, { day: '14 Sat', xp: 0 }
];

export default function Dashboard() {
  const stats = { level: 1, xp: 402, nextXp: 500, quizzes: 9, avgScore: 74, correct: 29, perfect: 4 };

  return (
    <div className="dashboard-wrapper">
      {/* ... keep your existing Header and Hero Banner code here ... */}

      {/* --- NEW GRAPH SECTION --- */}
      <div className="dashboard-chart-card">
        <div className="chart-header">
          <TrendingUp size={20} color="#0d9488" />
          <h3>Learning Activity (14 Days)</h3>
        </div>

        <div className="chart-container" style={{ width: '100%', height: 300 }}>
          <ResponsiveContainer>
            <AreaChart data={activityData}>
              <defs>
                <linearGradient id="colorXp" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#2dd4bf" stopOpacity={0.3}/>
                  <stop offset="95%" stopColor="#2dd4bf" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis 
                dataKey="day" 
                axisLine={false} 
                tickLine={false} 
                tick={{fill: '#64748b', fontSize: 12}}
                dy={10}
              />
              <YAxis 
                axisLine={false} 
                tickLine={false} 
                tick={{fill: '#64748b', fontSize: 12}}
                domain={[0, 4]} 
              />
              <Tooltip 
                contentStyle={{ borderRadius: '10px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
              />
              <Area 
                type="monotone" 
                dataKey="xp" 
                stroke="#2dd4bf" 
                strokeWidth={3}
                fillOpacity={1} 
                fill="url(#colorXp)" 
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* ... keep your existing Stats Grid code here ... */}
    </div>
  );
}
